# The game's marks (#525): logos built from the game's own things, each its own design (no shared template). Raids,
# Legends and story chapters show them on their cutscene title cards; Trials, the Bloodsand Brawl and Honor at the top
# of their screens. Writes art/brand/marks/<key>.svg and src/art_marks.js (ART.marks[key]).
# python3 art/brand/marks.py [--sheet] [key …]   (the sheet: art/brand/marks_sheet.png; with keys, only those, bigger)
import os, sys, json, re, math, subprocess, base64
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from lockup import word, centred, GOLD, metal, ROOT, CAP, _cm, _gs, _hm, _upm
from fontTools.pens.svgPathPen import SVGPathPen
from fontTools.pens.transformPen import TransformPen
H = os.path.dirname(os.path.abspath(__file__)); OUT = os.path.join(H, 'marks'); os.makedirs(OUT, exist_ok=True)
W, HT, INK = 640, 320, '#120c08'
J = ' stroke-linejoin="round" stroke-linecap="round"'

def arc(text, size, cx, cy, r, track=0.04):
    """text along a circle of radius r around (cx, cy), bent like a rainbow (the centre below the text)"""
    k = size / _upm; adv = []
    for ch in text: adv.append(size * 0.32 if ch == ' ' else _hm[_cm[ord(ch)]][0] * k + track * size)
    tot = sum(adv) - track * size; pen = SVGPathPen(_gs); x = -tot / 2
    for ch, a in zip(text, adv):
        if ch != ' ':
            hw = (a - track * size) / 2; t = (x + hw) / r; c, s = math.cos(t), math.sin(t)
            px, py = cx + r * math.sin(t), cy - r * math.cos(t)
            _gs[_cm[ord(ch)]].draw(TransformPen(pen, (k * c, k * s, k * s, -k * c, px - hw * c, py - hw * s)))
        x += a
    return re.sub(r'(\d+\.\d)\d+', r'\1', pen.getCommands())

def fit(text, maxsize, maxw, track=0.04):
    s = maxsize
    while s > 16 and word(text, s, 0, 0, track)[1] > maxw: s -= 2
    return s

class Mark:
    """one logo: its own gradients (ids prefixed by the key, so two on one page never clash) and carved letters"""
    def __init__(s, key):
        s.p = re.sub(r'[^a-z0-9]', '', key); s.defs = [GOLD.format(id=s.p + 'G')]; s.n = 0
    def grad(s, name, c):
        s.defs.append(metal(s.p + name, c)); return f'url(#{s.p}{name})'
    def raw(s, d): s.defs.append(d)
    def id(s, name): return s.p + name
    @property
    def gold(s): return f'url(#{s.p}G)'
    def carve(s, d, sw, fill, ink=INK, light=.45, drop=4):
        """the outline once, then a drop shadow, a stroked fill and a thin top light"""
        s.n += 1; i = f'{s.p}t{s.n}'; s.defs.append(f'<path id="{i}" d="{d}"/>')
        return ((f'<use href="#{i}" fill="{ink}" stroke="{ink}" stroke-width="{sw}"{J} transform="translate(0,{drop})"/>' if drop else '')
                + f'<use href="#{i}" fill="{fill}" stroke="{ink}" stroke-width="{sw}"{J} paint-order="stroke"/>'
                + (f'<use href="#{i}" fill="none" stroke="#ffffff" stroke-width="1" opacity="{light}" transform="translate(0,-1)"/>' if light else ''))
    def use(s, n, **a): return f'<use href="#{s.p}t{n}" ' + ' '.join(f'{k.replace("_", "-")}="{v}"' for k, v in a.items()) + '/>'
    def blur(s, sd=10):
        s.defs.append(f'<filter id="{s.p}B{sd}" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="{sd}"/></filter>'); return f'url(#{s.p}B{sd})'
    def svg(s, body, title):
        return (f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{HT}" viewBox="0 0 {W} {HT}">\n  <!-- {title}. Generated by art/brand/marks.py -->\n'
                f'  <defs>{"".join(dict.fromkeys(s.defs))}</defs>\n  {body}\n</svg>\n')  # a def used twice is written once (#528)

def small(m, text, size, base, fill, track=0.24, sw=4):
    d, w = centred(text, size, base, track, W); return m.carve(d, sw, fill, light=.3, drop=2), w

def rules(y, x0, x1, w, color='#f0c45a', gap=16, out=96):
    a, b = (W - w) / 2, (W + w) / 2
    r = lambda p, q: f'<path d="M{p:.1f},{y} L{q:.1f},{y}" stroke="{INK}" stroke-width="5"/><path d="M{p:.1f},{y} L{q:.1f},{y}" stroke="{color}" stroke-width="2"/>'
    return r(max(x0, a - gap - out), a - gap) + r(b + gap, min(x1, b + gap + out))

def chain(x, y0, n, metal_c='#9a9aa4'):
    return ''.join(f'<ellipse cx="{x}" cy="{y0 + i * 10}" rx="{3 if i % 2 else 5}" ry="6" fill="none" stroke="{INK}" stroke-width="4"/>'
                   f'<ellipse cx="{x}" cy="{y0 + i * 10}" rx="{3 if i % 2 else 5}" ry="6" fill="none" stroke="{metal_c}" stroke-width="2"/>' for i in range(n))

# ---------------------------------------------------------------- raids
def magma():  # molten letters on a cracked basalt slab, the throne rising out of the fire behind
    m = Mark('raid_molten_core'); hot = m.grad('hot', ('#fffbe0', '#ffd050', '#e0501a', '#ff8a2a', '#6a0c04')); bl = m.blur(9)
    slab = 'M34,170 L120,150 L210,162 L320,146 L430,160 L520,148 L606,170 L590,262 L470,276 L320,266 L170,278 L50,262 Z'
    flames = ''.join(f'<path d="M{x},{y} C{x - 14 * f},{y - 30} {x + 10 * f},{y - 44} {x},{y - 70} C{x + 24 * f},{y - 44} {x + 26 * f},{y - 20} {x + 8 * f},{y} Z" fill="#ff7a1a" stroke="#7a1a04" stroke-width="2"/>'
                     f'<path d="M{x + 2 * f},{y - 4} C{x - 4 * f},{y - 20} {x + 6 * f},{y - 30} {x + 2 * f},{y - 44} C{x + 12 * f},{y - 28} {x + 12 * f},{y - 14} {x + 6 * f},{y - 4} Z" fill="#ffe070"/>'
                     for x, y, f in [(214, 154, 1), (426, 154, -1), (178, 160, 1), (462, 160, -1)])
    throne = (f'<g transform="translate(320,150) scale(1.7)"><path d="M-24,0 L-24,-58 L-14,-74 L-6,-60 L0,-82 L6,-60 L14,-74 L24,-58 L24,0 Z" fill="#2a1208" stroke="{INK}" stroke-width="2.4"{J}/>'
              f'<path d="M-24,-22 L-34,-22 L-34,0 M24,-22 L34,-22 L34,0" fill="none" stroke="{INK}" stroke-width="3"/><path d="M-12,-46 L12,-46 L12,-18 L-12,-18 Z" fill="#ff6a1a" opacity=".9"/>'
              '<path d="M-24,-58 L-14,-74 L-6,-60 L0,-82 L6,-60 L14,-74 L24,-58" fill="none" stroke="#ffb040" stroke-width="1.4"/></g>')
    cracks = '<path d="M60,244 L96,230 L120,248 M520,236 L556,250 L580,234 M250,272 L280,260 M380,264 L410,274" stroke="#ff6a1a" stroke-width="2.2" fill="none"/>'
    ns = fit('MAGMA THRONE', 74, 540); nd, _ = centred('MAGMA THRONE', ns, 240, 0.04, W)
    drips = ''.join(f'<path d="M{x},240 Q{x + 4},{252 + l} {x},{256 + l} Q{x - 4},{252 + l} {x},240 Z" fill="#ff8a2a" stroke="#6a0c04" stroke-width="1.4"/>' for x, l in [(150, 6), (236, 12), (300, 4), (372, 10), (452, 6), (500, 14)])
    the, _ = small(m, 'THE', 22, 182, m.gold, 0.4)
    sub, sw = small(m, 'A RAID FOR TEN', 17, 306, hot)
    glow = m.carve(nd, 7, hot); i = m.n
    body = (f'<ellipse cx="320" cy="170" rx="250" ry="70" fill="#ff5a10" opacity=".35" filter="{bl}"/>{flames}{throne}'
            f'<path d="{slab}" fill="#1c0d08" stroke="{INK}" stroke-width="4"{J}/><path d="{slab}" fill="none" stroke="#5a2a14" stroke-width="1.6" transform="translate(0,3)"/>{cracks}'
            + m.use(i, fill='#ff5a10', opacity='.8', filter=bl) + drips + glow + the + rules(300, 30, 610, sw, '#ff8a2a') + sub)
    return m.svg(body, 'The Magma Throne')

def veshmira():  # wings that span the whole mark, a horned head with one slit eye, the name across the wings
    m = Mark('raid_onyxias_lair'); vio = m.grad('vio', ('#ffffff', '#d8b8ff', '#5a2a8a', '#a87ae0', '#2a1046')); bl = m.blur(12)
    wing = ('M318,130 C270,60 170,26 40,40 C70,58 78,76 70,96 C100,90 118,104 112,128 C140,118 164,130 160,156 C190,146 214,160 212,186 '
            'C240,172 270,176 286,196 C292,172 300,150 318,130 Z')
    bones = 'M318,130 C250,70 150,44 40,40 M300,140 C230,110 160,100 70,96 M290,160 C230,140 170,134 112,128 M288,176 C250,166 200,160 160,156 M290,186 C260,180 230,182 212,186'
    w1 = f'<path d="{wing}" fill="#2a1240" stroke="{INK}" stroke-width="4"{J}/><path d="{bones}" fill="none" stroke="#8a5ac0" stroke-width="2"/>'
    head = (f'<path d="M320,196 C300,170 296,130 306,100 L294,62 L312,86 L320,70 L328,86 L346,62 L334,100 C344,130 340,170 320,196 Z" fill="#160a22" stroke="{INK}" stroke-width="3"{J}/>'
            '<path d="M308,118 Q320,110 332,118 Q320,126 308,118 Z" fill="#ffd040"/><path d="M320,112 L320,124" stroke="#160a22" stroke-width="2.6"/>')
    ns = fit("VESHMIRA'S LAIR", 72, 560); nd, _ = centred("VESHMIRA'S LAIR", ns, 254, 0.04, W)
    sub, sw = small(m, 'A RAID FOR TEN', 17, 302, vio)
    smoke = ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{rx}" ry="10" fill="#6a3aa0" opacity=".3" filter="{bl}"/>' for x, y, rx in [(160, 266, 90), (480, 266, 90), (320, 282, 140)])
    body = (f'<ellipse cx="320" cy="120" rx="270" ry="90" fill="#7a3ad0" opacity=".25" filter="{bl}"/>{w1}<g transform="translate(640,0) scale(-1,1)">{w1}</g>'
            f'{head}{smoke}' + m.carve(nd, 7, vio) + rules(296, 40, 600, sw, '#a87ae0') + sub)
    return m.svg(body, "Veshmira's Lair")

def tidecrown():  # the crown and the citadel's spires above the water; the waterline cuts through TIDECROWN
    m = Mark('raid_tidecrown_citadel'); gold = m.gold; sea = m.grad('sea', ('#eafcff', '#8fe8f0', '#1a6a7a', '#4ab8c8', '#0a3440'))
    wl = 212; m.raw(f'<clipPath id="{m.id("up")}"><rect x="0" y="0" width="{W}" height="{wl}"/></clipPath><clipPath id="{m.id("dn")}"><rect x="0" y="{wl}" width="{W}" height="{HT}"/></clipPath>'
                    f'<radialGradient id="{m.id("w")}" cx=".5" cy="0" r=".5" gradientTransform="translate(0,0) scale(1,1)"><stop offset="0" stop-color="#0e5a6a" stop-opacity=".9"/><stop offset=".7" stop-color="#083a46" stop-opacity=".6"/><stop offset="1" stop-color="#04141c" stop-opacity="0"/></radialGradient>')
    spires = ''.join(f'<path d="M{x - w},{wl} L{x - w},{y} L{x},{y - 34} L{x + w},{y} L{x + w},{wl} Z" fill="#14303a" stroke="{INK}" stroke-width="3"{J}/>' for x, y, w in
                     [(196, 140, 10), (444, 140, 10), (232, 110, 14), (408, 110, 14), (270, 92, 10), (370, 92, 10)])
    crown = (f'<g transform="translate(320,86)"><path d="M-58,30 L-58,-22 L-30,4 L0,-44 L30,4 L58,-22 L58,30 Z" fill="{gold}" stroke="{INK}" stroke-width="4"{J}/>'
             f'<circle cx="0" cy="-48" r="7" fill="#8fe8f0" stroke="{INK}" stroke-width="2.4"/><circle cx="-58" cy="-26" r="5" fill="#8fe8f0" stroke="{INK}" stroke-width="2"/><circle cx="58" cy="-26" r="5" fill="#8fe8f0" stroke="{INK}" stroke-width="2"/>'
             f'<path d="M-58,30 L58,30 L58,40 L-58,40 Z" fill="{gold}" stroke="{INK}" stroke-width="3"/></g>')
    nd, _ = centred('TIDECROWN', 84, 240, 0.05, W); the, _ = small(m, 'THE', 20, 152, gold, 0.4)
    cd, _ = centred('CITADEL', 32, 280, 0.3, W)
    up = m.carve(nd, 7, gold); dn = m.use(m.n, fill=sea, stroke=INK, stroke_width=7, paint_order='stroke')
    ripples = ''.join(f'<path d="M{x},{y} q12,-6 24,0 t24,0" stroke="#8fe8f0" stroke-width="2" fill="none" opacity="{o}"/>' for x, y, o in [(50, 226, .8), (530, 230, .8), (110, 288, .5), (480, 292, .5)])
    bubbles = ''.join(f'<circle cx="{x}" cy="{y}" r="{r}" fill="none" stroke="#bff4f8" stroke-width="1.4" opacity=".7"/>' for x, y, r in [(110, 250, 4), (120, 236, 2.4), (540, 260, 3.6), (530, 246, 2), (590, 232, 2.6)])
    sub, sw = small(m, 'A RAID FOR TEN', 15, 308, sea)
    wave = 'M20,{0} '.format(wl) + ' '.join('q20,-8 40,0' if i == 0 else 't40,0' for i in range(15))
    body = (f'{spires}{crown}<g clip-path="url(#{m.id("up")})">{up}</g>'
            f'<ellipse cx="320" cy="{wl}" rx="330" ry="{HT - wl + 10}" fill="url(#{m.id("w")})" clip-path="url(#{m.id("dn")})"/><g clip-path="url(#{m.id("dn")})">{dn}</g>'
            f'<path d="{wave}" stroke="{INK}" stroke-width="5" fill="none"/><path d="{wave}" stroke="#bff4f8" stroke-width="2.4" fill="none"/>'
            + the + m.carve(cd, 5, sea, light=.3) + ripples + bubbles + sub)
    return m.svg(body, 'The Tidecrown Citadel')

# ---------------------------------------------------------------- Legends
def lyveus():  # a knight's sword through the name, a torn red ribbon for the exile
    m = Mark('legend_lyveus'); st = m.grad('st', ('#ffffff', '#dfe6f0', '#4a5260', '#a8b2c2', '#262c36')); gold = m.gold
    sword = (f'<path d="M311,96 L329,96 L329,252 L320,288 L311,252 Z" fill="{st}" stroke="{INK}" stroke-width="3.4"{J}/><path d="M320,100 L320,264" stroke="#7a8494" stroke-width="1.6"/>'
             f'<path d="M244,82 Q320,96 396,82 L392,98 Q320,108 248,98 Z" fill="{gold}" stroke="{INK}" stroke-width="3.4"{J}/>'
             f'<path d="M313,30 L327,30 L327,82 L313,82 Z" fill="#3a2a1a" stroke="{INK}" stroke-width="3"/><path d="M313,42 L327,50 M313,56 L327,64 M313,70 L327,78" stroke="#8a6a3a" stroke-width="2"/>'
             f'<circle cx="320" cy="22" r="11" fill="{gold}" stroke="{INK}" stroke-width="3"/><circle cx="320" cy="22" r="4" fill="#8fd0ff"/>')
    ns = fit('LYVEUS CLOVEUS', 66, 580); nd, _ = centred('LYVEUS CLOVEUS', ns, 178, 0.05, W)
    rib = 'M96,212 Q320,188 544,212 L556,234 L544,256 Q320,232 96,256 L84,234 Z'
    tear = 'M84,234 L62,220 L72,234 L58,250 Z M556,234 L578,220 L568,234 L582,250 Z'
    sd = arc('THE EXILED KNIGHT', 19, 320, 241 + 1300, 1300, 0.22)
    leg, lw = small(m, 'LEGENDS', 16, 300, st, 0.5)
    body = (f'<ellipse cx="320" cy="150" rx="200" ry="110" fill="#8fb0ff" opacity=".14" filter="{m.blur(14)}"/>{sword}' + m.carve(nd, 7, st)
            + f'<path d="{tear}" fill="#3a0e0e" stroke="{INK}" stroke-width="3"{J}/><path d="{rib}" fill="#6a1414" stroke="{INK}" stroke-width="4"{J}/>'
            + m.carve(sd, 3, gold, light=.25, drop=2) + rules(294, 60, 580, lw, '#a8b2c2') + leg)
    return m.svg(body, 'Lyveus Cloveus, the Exiled Knight')

def widya():  # the name sung along an arc over a staff of lute strings, reeds at the edges, notes in the air
    m = Mark('legend_widya'); rd = m.grad('rd', ('#fbfff0', '#cfeaa0', '#3a6a1a', '#8ac04a', '#1e400c')); gold = m.gold
    ys = list(range(204, 254, 11))
    staff = ''.join(f'<path d="M40,{y} Q320,{y - 26} 600,{y}" stroke="{INK}" stroke-width="4" fill="none"/>' for y in ys) + ''.join(f'<path d="M40,{y} Q320,{y - 26} 600,{y}" stroke="#e0c070" stroke-width="1.6" fill="none"/>' for y in ys)
    note = lambda x, y, s: (f'<g transform="translate({x},{y}) scale({s})"><ellipse cx="0" cy="0" rx="7" ry="5" transform="rotate(-20)" fill="{gold}" stroke="{INK}" stroke-width="2"/>'
                            f'<path d="M6,-2 L6,-30 Q14,-24 18,-14" stroke="{INK}" stroke-width="5" fill="none"/><path d="M6,-2 L6,-30 Q14,-24 18,-14" stroke="#f0c45a" stroke-width="2" fill="none"/></g>')
    reeds = ''.join(f'<path d="M{x},320 Q{x + b},200 {x + b * 1.6},{t}" stroke="{INK}" stroke-width="6" fill="none"/><path d="M{x},320 Q{x + b},200 {x + b * 1.6},{t}" stroke="#8ac04a" stroke-width="3" fill="none"/>'
                    f'<ellipse cx="{x + b * 1.6}" cy="{t + 10}" rx="5" ry="14" fill="#6a4a1a" stroke="{INK}" stroke-width="2"/>' for x, b, t in
                    [(24, 10, 120), (44, -6, 150), (10, 18, 170), (616, -10, 120), (596, 6, 150), (630, -18, 170)])
    lute = (f'<g transform="translate(320,62) rotate(-28)"><path d="M-4,-8 L-4,-56 L-8,-64 L8,-68 L4,-56 L4,-8 Z" fill="#7a4a1a" stroke="{INK}" stroke-width="2.6"{J}/>'
            f'<ellipse cx="0" cy="20" rx="24" ry="30" fill="{gold}" stroke="{INK}" stroke-width="3"/><circle cx="0" cy="14" r="7" fill="#3a2a10"/>'
            '<path d="M-2,-58 L-2,44 M2,-58 L2,44" stroke="#fff" stroke-width=".8" opacity=".8"/></g>')
    nd = arc('WIDYA', 96, 320, 192 + 520, 520, 0.08)
    sd, _ = centred("THE SONGKEEPER'S DAUGHTER", 17, 290, 0.2, W); leg, _ = small(m, 'LEGENDS', 14, 314, rd, 0.5)
    body = (f'<ellipse cx="320" cy="170" rx="230" ry="90" fill="#c8f07a" opacity=".16" filter="{m.blur(14)}"/>{reeds}{staff}{lute}'
            + note(128, 214, 1) + note(520, 220, 1.1) + note(180, 150, .8) + note(470, 140, .8) + note(90, 176, .7)
            + m.carve(nd, 8, rd) + m.carve(sd, 4, gold, light=.3, drop=2) + leg)
    return m.svg(body, "Widya, the Songkeeper's Daughter")

def bromli():  # a tavern sign on chains: the name painted on the plank, a foaming tankard and a hammer
    m = Mark('legend_bromli'); ale = m.grad('ale', ('#fff4d0', '#f8c860', '#8a4a0c', '#e0982a', '#5a2c04')); gold = m.gold
    m.raw(f'<linearGradient id="{m.id("wd")}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#7a4a22"/><stop offset=".5" stop-color="#5a3216"/><stop offset="1" stop-color="#3a1e0a"/></linearGradient>')
    bar = f'<path d="M60,30 L580,30" stroke="{INK}" stroke-width="12" stroke-linecap="round"/><path d="M60,30 L580,30" stroke="#5a5a62" stroke-width="6" stroke-linecap="round"/>'
    plank = 'M70,80 Q320,70 570,80 L578,226 Q320,236 62,226 Z'
    grain = ''.join(f'<path d="M80,{y} Q320,{y - 8 + i % 3 * 5} 562,{y}" stroke="#2a1406" stroke-width="1.4" fill="none" opacity=".6"/>' for i, y in enumerate(range(96, 222, 18)))
    d1, _ = centred('BROMLI', 70, 150, 0.08, W); d2, _ = centred('BEERHAMMER', 44, 208, 0.08, W)
    tank = (f'<g transform="translate(70,214) rotate(-10)"><path d="M-22,-46 L22,-46 L20,10 L-20,10 Z" fill="{ale}" stroke="{INK}" stroke-width="3.4"{J}/>'
            f'<path d="M22,-34 Q42,-34 40,-18 Q40,-2 21,-2" fill="none" stroke="{INK}" stroke-width="8"/><path d="M22,-34 Q42,-34 40,-18 Q40,-2 21,-2" fill="none" stroke="#e0982a" stroke-width="3"/>'
            f'<path d="M-26,-46 Q-28,-62 -12,-60 Q-6,-72 6,-64 Q18,-72 24,-58 Q36,-56 26,-44 L-24,-44 Z" fill="#fff8e6" stroke="{INK}" stroke-width="2.6"{J}/>'
            f'<path d="M-12,-36 L-12,2 M0,-36 L0,2 M12,-36 L12,2" stroke="#8a4a0c" stroke-width="2"/></g>')
    hammer = (f'<g transform="translate(572,214) rotate(18)"><path d="M0,-80 L0,30" stroke="{INK}" stroke-width="11" stroke-linecap="round"/><path d="M0,-80 L0,30" stroke="#8a5a2a" stroke-width="6" stroke-linecap="round"/>'
              f'<path d="M-30,-100 L30,-100 L30,-66 L-30,-66 Z" fill="#8a8a94" stroke="{INK}" stroke-width="3.4"{J}/><path d="M-30,-92 L30,-92" stroke="#d0d0d8" stroke-width="2"/></g>')
    plaque = 'M232,252 L408,252 L408,294 L232,294 Z'
    sd, _ = centred('THE UNSUNG', 18, 281, 0.24, W); leg, _ = centred('LEGENDS', 14, 64, 0.5, W)
    body = (bar + chain(120, 38, 4) + chain(520, 38, 4) + f'<path d="{plank}" fill="url(#{m.id("wd")})" stroke="{INK}" stroke-width="5"{J}/>{grain}'
            f'<path d="{plank}" fill="none" stroke="#a87a42" stroke-width="1.6" transform="translate(0,2)"/>' + m.carve(d1, 7, ale) + m.carve(d2, 5, ale)
            + chain(290, 236, 2) + chain(350, 236, 2) + f'<path d="{plaque}" fill="#3a1e0a" stroke="{INK}" stroke-width="4"{J}/>' + m.carve(sd, 3, gold, light=.3, drop=1)
            + f'<path d="{leg}" fill="#d0d0d8"/>' + tank + hammer)
    return m.svg(body, 'Bromli Beerhammer, the Unsung')

# ---------------------------------------------------------------- story chapters
def prologue():  # a dove carrying a coin on a thread over an open book: the borrowed peace
    m = Mark('chapter_intro'); gold = m.gold; iv = m.grad('iv', ('#ffffff', '#f6ead0', '#8a6a3a', '#d8c090', '#5a4220'))
    dove = (f'<g transform="translate(320,62)"><path d="M-40,6 Q-10,-6 6,2 Q22,-4 40,-2 Q28,6 16,8 Q12,22 -6,24 Q-28,22 -40,6 Z" fill="#fffaf0" stroke="{INK}" stroke-width="3"{J}/>'
            f'<path d="M-6,4 Q-30,-34 -64,-40 Q-40,-14 -30,4 Z" fill="#fffaf0" stroke="{INK}" stroke-width="3"{J}/><path d="M2,2 Q20,-36 56,-46 Q40,-18 22,4 Z" fill="#f0ead8" stroke="{INK}" stroke-width="3"{J}/>'
            f'<circle cx="32" cy="-1" r="2" fill="{INK}"/><path d="M40,-2 L48,0 L40,3" fill="#e0a040" stroke="{INK}" stroke-width="1.4"/>'
            f'<path d="M-2,22 L-2,52" stroke="#c8a050" stroke-width="1.6"/><circle cx="-2" cy="62" r="12" fill="{gold}" stroke="{INK}" stroke-width="3"/><circle cx="-2" cy="62" r="7" fill="none" stroke="{INK}" stroke-width="1.2" opacity=".6"/></g>')
    book = (f'<path d="M80,300 Q200,274 320,294 Q440,274 560,300 L560,282 Q440,256 320,276 Q200,256 80,282 Z" fill="{iv}" stroke="{INK}" stroke-width="3.4"{J}/>'
            f'<path d="M320,276 L320,294" stroke="{INK}" stroke-width="2"/>'
            + ''.join(f'<path d="M{a},{y} Q{(a + b) / 2},{y - 6} {b},{y}" stroke="#8a6a3a" stroke-width="1.4" fill="none"/>' for a, b, y in [(110, 290, 284), (350, 530, 284), (120, 280, 291), (360, 520, 291)]))
    nd, _ = centred('THE BORROWED PEACE', fit('THE BORROWED PEACE', 60, 560), 236, 0.04, W)
    pro, pw = small(m, 'PROLOGUE', 20, 168, gold, 0.5)
    body = (f'<ellipse cx="320" cy="110" rx="170" ry="80" fill="#fff0c0" opacity=".14" filter="{m.blur(14)}"/>{dove}' + pro + rules(161, 60, 580, pw)
            + m.carve(nd, 7, iv) + book)
    return m.svg(body, 'Prologue: The Borrowed Peace')

def ch1():  # a debt note: the name inked on torn parchment, sealed in red wax
    m = Mark('chapter_ch1'); m.raw(f'<linearGradient id="{m.id("pp")}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#f4e6c4"/><stop offset="1" stop-color="#cfb684"/></linearGradient>')
    torn = 'M70,52 L130,46 L150,54 L220,44 L300,52 L360,42 L430,50 L500,44 L572,52 L566,110 L574,170 L566,232 L572,276 L500,268 L440,278 L370,270 L300,280 L230,270 L160,278 L96,268 L66,276 L74,214 L64,160 L72,100 Z'
    nd, _ = centred('DEBTS COME DUE', fit('DEBTS COME DUE', 66, 450), 188, 0.03, W)
    ch, _ = centred('CHAPTER ONE', 18, 104, 0.4, W)
    lines = ''.join(f'<path d="M{a},{y} L{b},{y}" stroke="#a88a5a" stroke-width="1.4"/>' for a, b, y in [(120, 520, 122), (120, 520, 214), (120, 400, 232), (120, 360, 250)])
    seal = (f'<g transform="translate(500,238) rotate(-12)"><path d="M0,-34 Q22,-36 32,-16 Q40,4 30,22 Q14,38 -6,34 Q-30,32 -34,10 Q-38,-14 -22,-28 Q-12,-36 0,-34 Z" fill="#9a1a14" stroke="{INK}" stroke-width="3"{J}/>'
            f'<circle r="20" fill="none" stroke="#5a0a08" stroke-width="2"/><path d="M0,-11 L0,11 M-8,-11 L8,-11 M-8,11 L8,11" stroke="#e05a4a" stroke-width="3.4" fill="none"/>'
            '<path d="M-14,-18 Q-6,-26 6,-24" stroke="#ff9a8a" stroke-width="2" fill="none" opacity=".7"/></g>')
    sig = '<path d="M140,252 q10,-14 20,0 t20,-2 q8,-10 16,4" stroke="#3a2a1a" stroke-width="1.8" fill="none"/>'
    body = (f'<path d="{torn}" fill="#000" transform="translate(5,8)" opacity=".6"/><g transform="rotate(-2 320 160)"><path d="{torn}" fill="url(#{m.id("pp")})" stroke="#6a4a22" stroke-width="2.4"{J}/>'
            f'{lines}<path d="{ch}" fill="#6a4a22"/><path d="{nd}" fill="#1e1208" stroke="#1e1208" stroke-width="1.6"{J}/>{sig}</g>{seal}')
    return m.svg(body, 'Chapter One: Debts Come Due')

def ch2():  # three ships on the horizon at sunset, a coin on every sail; the name on the water
    m = Mark('chapter_ch2'); gold = m.gold; sea = m.grad('sea', ('#fff6d8', '#f0c45a', '#2a4a5a', '#c8a050', '#0c2430'))
    ship = lambda x, y, s: (f'<g transform="translate({x},{y}) scale({s})"><path d="M-46,0 L46,0 L34,18 L-34,18 Z" fill="#2a1a10" stroke="{INK}" stroke-width="3"{J}/>'
                            f'<path d="M0,0 L0,-84" stroke="{INK}" stroke-width="4"/><path d="M4,-80 Q40,-50 4,-12 Z" fill="#e8dcc0" stroke="{INK}" stroke-width="3"{J}/>'
                            f'<path d="M-4,-70 Q-36,-44 -4,-14 Z" fill="#d8ccb0" stroke="{INK}" stroke-width="3"{J}/><circle cx="16" cy="-46" r="9" fill="{gold}" stroke="{INK}" stroke-width="2"/>'
                            f'<path d="M0,-84 L18,-90 L0,-96" fill="#9a1a14" stroke="{INK}" stroke-width="1.6"/></g>')
    waves = ''.join(f'<path d="M{x0},{y} q15,-7 30,0 t30,0 t30,0 t30,0 t30,0 t30,0" stroke="{c}" stroke-width="2.4" fill="none" opacity="{o}"/>' for x0, y, c, o in
                    [(40, 162, '#6ab0c0', .8), (420, 166, '#6ab0c0', .8), (200, 176, '#4a8090', .6), (60, 296, '#4a8090', .5), (420, 298, '#4a8090', .5)])
    nd, _ = centred("THE COLLECTOR'S FLEET", fit("THE COLLECTOR'S FLEET", 60, 580), 236, 0.04, W)
    ch, cw = small(m, 'CHAPTER TWO', 18, 280, gold, 0.4)
    body = (f'<circle cx="320" cy="140" r="64" fill="#f0a040" opacity=".4" filter="{m.blur(12)}"/><path d="M262,154 A58,58 0 0 1 378,154 Z" fill="#e8903a" opacity=".85"/>'
            f'<path d="M20,154 L620,154" stroke="#6ab0c0" stroke-width="2"/>' + ship(190, 146, .8) + ship(450, 146, .8) + ship(320, 152, 1.08) + waves
            + m.carve(nd, 7, sea) + rules(273, 60, 580, cw) + ch)
    return m.svg(body, "Chapter Two: The Collector's Fleet")

def ch3():  # a magnifying glass over the ledger: the lens enlarges AUDIT
    m = Mark('chapter_ch3'); gold = m.gold; ink2 = m.grad('ik', ('#fff6dc', '#efdcb0', '#6a4a22', '#c8a870', '#3a2410'))
    cols = ''.join(f'<path d="M{x},{y} L{x + 70},{y}" stroke="#8a6a3a" stroke-width="2" opacity=".55"/>' for x in (50, 150, 420, 520) for y in range(96, 150, 12))
    td, _ = centred('THE', 30, 150, 0.3, W); ad, _ = centred('AUDIT', 104, 254, 0.06, W)
    _, wa = word('AUDIT', 104, 0, 0, 0.06); _, wpre = word('AUD', 104, 0, 0, 0.06); _, wi = word('I', 104, 0, 0, 0.06)
    cx, cy, r = (W - wa) / 2 + wpre + 0.06 * 104 + (wi - 0.06 * 104) / 2, 218, 48
    m.raw(f'<clipPath id="{m.id("lens")}"><circle cx="{cx}" cy="{cy}" r="{r}"/></clipPath>')
    txt = m.carve(ad, 8, ink2); i = m.n
    big = (f'<g clip-path="url(#{m.id("lens")})"><circle cx="{cx}" cy="{cy}" r="{r}" fill="#24180c"/><g transform="translate({cx},{cy}) scale(1.3) translate({-cx},{-cy})">'
           + m.use(i, fill=gold, stroke=INK, stroke_width=6, paint_order='stroke') + '</g></g>')
    lens = (f'<path d="M{cx + 34},{cy + 34} L{cx + 74},{cy + 74}" stroke="{INK}" stroke-width="22" stroke-linecap="round"/><path d="M{cx + 34},{cy + 34} L{cx + 74},{cy + 74}" stroke="#5a3216" stroke-width="13" stroke-linecap="round"/>'
            f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="none" stroke="{INK}" stroke-width="15"/><circle cx="{cx}" cy="{cy}" r="{r}" fill="none" stroke="{gold}" stroke-width="8"/>'
            f'<path d="M{cx - 36},{cy - 28} A38,38 0 0 1 {cx + 4},{cy - 38}" stroke="#ffffff" stroke-width="4" fill="none" opacity=".5"/>')
    ch, cw = small(m, 'CHAPTER THREE', 18, 60, gold, 0.4)
    body = ch + rules(54, 60, 580, cw) + cols + m.carve(td, 5, ink2, light=.3) + txt + big + lens
    return m.svg(body, 'Chapter Three: The Audit')

def ch4():  # the mountain wakes: CINDERPEAK arches over the peak, embers rise, RISING below
    m = Mark('chapter_ch4'); fire = m.grad('fr', ('#fff6c0', '#ffc050', '#a8300c', '#f07a2a', '#4a0c04')); gold = m.gold
    mtn = 'M80,290 L222,176 L262,200 L320,126 L376,196 L414,172 L560,290 Z'
    lava = 'M320,126 L306,156 L322,176 L310,208 L326,234 M320,126 L338,164 L352,192'
    embers = ''.join(f'<circle cx="{x}" cy="{y}" r="{r}" fill="#ffb040" opacity="{o}"/>' for x, y, r, o in
                     [(300, 108, 3, .9), (334, 96, 2.4, .8), (312, 86, 2, .7), (346, 114, 2, .9), (290, 94, 1.6, .6)])
    smoke = ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{rx}" ry="{ry}" fill="#3a3030" opacity=".45" filter="{m.blur(8)}"/>' for x, y, rx, ry in [(320, 104, 36, 20), (306, 84, 44, 18)])
    nd = arc('CINDERPEAK', 66, 320, 104 + 300, 300, 0.06)
    rd, _ = centred('RISING', 40, 282, 0.5, W)
    ch, cw = small(m, 'CHAPTER FOUR', 16, 22, gold, 0.4)
    body = (f'<ellipse cx="320" cy="210" rx="190" ry="90" fill="#ff5a10" opacity=".3" filter="{m.blur(16)}"/>{smoke}'
            f'<path d="{mtn}" fill="#1e120c" stroke="{INK}" stroke-width="4"{J}/><path d="{lava}" stroke="#ff7a1a" stroke-width="3.6" fill="none"/><path d="{lava}" stroke="#ffe080" stroke-width="1.2" fill="none"/>'
            f'{embers}' + ch + m.carve(nd, 7, fire) + m.carve(rd, 6, fire))
    return m.svg(body, 'Chapter Four: Cinderpeak Rising')

def ch5():  # a balance with books on one pan and coins on the other, still level
    m = Mark('chapter_ch5'); gold = m.gold; br = m.grad('br', ('#fff1c8', '#e8b860', '#7a4a14', '#c8902a', '#4a2a08'))
    beam = (f'<path d="M320,30 L320,150" stroke="{INK}" stroke-width="10"/><path d="M320,30 L320,150" stroke="{gold}" stroke-width="5"/>'
            f'<path d="M300,150 L340,150 L352,164 L288,164 Z" fill="{gold}" stroke="{INK}" stroke-width="3"{J}/>'
            f'<path d="M150,48 L490,48" stroke="{INK}" stroke-width="10" stroke-linecap="round"/><path d="M150,48 L490,48" stroke="{gold}" stroke-width="5" stroke-linecap="round"/>'
            f'<circle cx="320" cy="30" r="9" fill="{gold}" stroke="{INK}" stroke-width="3"/>')
    pan = lambda x: (f'<path d="M{x},48 L{x - 44},116 M{x},48 L{x + 44},116" stroke="{INK}" stroke-width="2.4"/>'
                     f'<path d="M{x - 52},116 L{x + 52},116 Q{x + 40},134 {x},134 Q{x - 40},134 {x - 52},116 Z" fill="{gold}" stroke="{INK}" stroke-width="3"{J}/>')
    books = ''.join(f'<path d="M{x - w / 2},{y} L{x + w / 2},{y} L{x + w / 2},{y + 12} L{x - w / 2},{y + 12} Z" fill="{c}" stroke="{INK}" stroke-width="2.4"/>'
                    for x, y, w, c in [(150, 104, 70, '#6a1a14'), (154, 92, 62, '#1a3a5a'), (148, 80, 54, '#3a5a1a')])
    coins = ''.join(f'<ellipse cx="{x}" cy="{y}" rx="16" ry="5" fill="{gold}" stroke="{INK}" stroke-width="2"/>' for x, y in
                    [(476, 110), (500, 110), (464, 103), (488, 103), (470, 96), (482, 89), (494, 96)])
    d1, _ = centred('BALANCING', 64, 228, 0.06, W); d2, _ = centred('THE BOOKS', 40, 272, 0.2, W)
    ch, cw = small(m, 'CHAPTER FIVE', 16, 308, gold, 0.4)
    body = beam + pan(150) + pan(490) + books + coins + m.carve(d1, 7, br) + m.carve(d2, 5, br) + rules(302, 60, 580, cw) + ch
    return m.svg(body, 'Chapter Five: Balancing the Books')

def ch6():  # a coin eclipsed: a black disc with a gold corona, chains hanging from the name
    m = Mark('chapter_ch6'); iron = m.grad('ir', ('#e8e0d0', '#9a9488', '#2a2620', '#5a544a', '#14120e')); gold = m.gold
    m.raw(f'<radialGradient id="{m.id("co")}"><stop offset=".55" stop-color="#ffd060" stop-opacity=".95"/><stop offset=".72" stop-color="#ff9a2a" stop-opacity=".5"/><stop offset="1" stop-color="#ff9a2a" stop-opacity="0"/></radialGradient>')
    rays = ''.join(f'<path d="M{320 + 54 * math.cos(a):.1f},{86 + 54 * math.sin(a):.1f} L{320 + (80 if i % 2 else 66) * math.cos(a):.1f},{86 + (80 if i % 2 else 66) * math.sin(a):.1f}" stroke="#ffc850" stroke-width="2" opacity=".7"/>'
                   for i, a in enumerate([j / 24 * 6.2832 for j in range(24)]))
    ecl = f'<circle cx="320" cy="86" r="84" fill="url(#{m.id("co")})"/>{rays}<circle cx="320" cy="86" r="48" fill="#0a0806" stroke="#ffe080" stroke-width="2"/><circle cx="320" cy="86" r="41" fill="none" stroke="#2a2218" stroke-width="2"/>'
    nd, _ = centred('THE CREDITOR', fit('THE CREDITOR', 74, 560), 258, 0.05, W)
    ch, _ = small(m, 'CHAPTER SIX', 18, 190, gold, 0.4)
    body = ecl + ch + chain(150, 268, 5, '#6a6458') + chain(490, 268, 5, '#6a6458') + m.carve(nd, 8, iron, light=.6)
    return m.svg(body, 'Chapter Six: The Creditor')

# ---------------------------------------------------------------- modes
def trials():  # the hourglass is the I in TRIALS; laurels close it in
    m = Mark('mode_trials'); gold = m.gold; base, size = 214, 100
    _, w1 = word('TR', size, 0, 0, 0.06); _, w2 = word('ALS', size, 0, 0, 0.06); gw = 60; tot = w1 + gw + w2 + 24
    x0 = (W - tot) / 2; d1, _ = word('TR', size, x0, base, 0.06); d2, _ = word('ALS', size, x0 + w1 + gw + 24, base, 0.06)
    gx, top = x0 + w1 + 12 + gw / 2, base - size * CAP
    hg = (f'<g transform="translate({gx:.1f},{(top + base) / 2:.1f})"><path d="M-22,-34 Q-22,-6 -4,0 Q-22,6 -22,34 L22,34 Q22,6 4,0 Q22,-6 22,-34 Z" fill="#fff6dc" fill-opacity=".92" stroke="{INK}" stroke-width="3.4"{J}/>'
          f'<path d="M-15,-20 L15,-20 Q10,-6 0,-1 Q-10,-6 -15,-20 Z M0,0 L0,24 M-17,31 Q0,16 17,31 Z" fill="#e0a840" stroke="#c88a2a" stroke-width="1.6"/>'
          f'<path d="M-30,-42 L30,-42 L30,-34 L-30,-34 Z M-30,34 L30,34 L30,42 L-30,42 Z" fill="{gold}" stroke="{INK}" stroke-width="3"{J}/></g>')
    leaf = lambda x, y, r, f: f'<path d="M0,-8 Q7,0 0,8 Q-7,0 0,-8 Z" transform="translate({x:.1f},{y:.1f}) rotate({r:.0f}) scale(1.5)" fill="{f}" stroke="{INK}" stroke-width="1.4"/>'
    laurel = ''.join(leaf(320 + sx * 290 * math.sin(t), 180 - 130 * math.cos(t), sx * math.degrees(t), '#8ab84a' if i % 2 else '#6a9a2a')
                     for sx in (1, -1) for i, t in enumerate([1.1 + j * 0.17 for j in range(9)]))
    sub, sw = small(m, 'PROVE IT AGAINST THE CLOCK', 16, 280, gold)
    body = (f'<ellipse cx="320" cy="170" rx="230" ry="80" fill="#ffc85a" opacity=".16" filter="{m.blur(14)}"/>{laurel}'
            + m.carve(d1, 8, gold) + m.carve(d2, 8, gold) + hg + rules(274, 50, 590, sw) + sub)
    return m.svg(body, 'Trials')

def brawl():  # crossed axes behind blood-red letters slashed by claws; arena sand below; THE on a round shield
    m = Mark('mode_brawl'); red = m.grad('rd', ('#ffe8d8', '#f07050', '#6a0c08', '#c83020', '#3a0604')); gold = m.gold
    axe = (f'<path d="M150,250 L470,40" stroke="{INK}" stroke-width="13" stroke-linecap="round"/><path d="M150,250 L470,40" stroke="#7a4a1e" stroke-width="7" stroke-linecap="round"/>'
           f'<path d="M430,40 Q500,10 520,70 Q490,60 470,74 Q460,52 430,40 Z" fill="#a0a0a8" stroke="{INK}" stroke-width="3.6"{J}/><path d="M440,44 Q496,22 512,62" stroke="#e8e8f0" stroke-width="2" fill="none"/>')
    sand = f'<path d="M0,262 Q160,236 320,248 Q480,236 640,262 L640,320 L0,320 Z" fill="#c8945a"/><path d="M0,262 Q160,236 320,248 Q480,236 640,262" stroke="{INK}" stroke-width="3" fill="none"/>'
    ns = fit('BLOODSAND BRAWL', 74, 600); nd, _ = centred('BLOODSAND BRAWL', ns, 220, 0.04, W)
    claws = ''.join(f'<path d="M{x},160 L{x + 30},228" stroke="#1a0402" stroke-width="5" stroke-linecap="round"/>' for x in (430, 446, 462))
    shield = f'<circle cx="320" cy="96" r="34" fill="#5a1a10" stroke="{INK}" stroke-width="4"/><circle cx="320" cy="96" r="28" fill="none" stroke="{gold}" stroke-width="3"/>'
    td, _ = centred('THE', 20, 103, 0.2, W); sd, _ = centred('RUMHOOK BAY', 17, 296, 0.4, W)
    body = (f'<ellipse cx="320" cy="170" rx="260" ry="80" fill="#ff3a1a" opacity=".22" filter="{m.blur(14)}"/>{axe}<g transform="translate(640,0) scale(-1,1)">{axe}</g>'
            + shield + m.carve(td, 3, gold, light=.3, drop=1) + sand + m.carve(nd, 8, red) + claws + f'<path d="{sd}" fill="#4a1a08"/>')
    return m.svg(body, 'The Bloodsand Brawl')

def honor():  # a war banner hung from a spear-pole: HONOR on the cloth, a medal on a ribbon hanging from it
    m = Mark('mode_honor'); gold = m.gold
    m.raw(f'<linearGradient id="{m.id("cl")}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#9a1a14"/><stop offset="1" stop-color="#4a0806"/></linearGradient>')
    pole = (f'<path d="M80,40 L560,40" stroke="{INK}" stroke-width="12" stroke-linecap="round"/><path d="M80,40 L560,40" stroke="#7a4a1e" stroke-width="6" stroke-linecap="round"/>'
            f'<path d="M560,30 L598,40 L560,50 Z M62,40 L80,30 L80,50 Z" fill="{gold}" stroke="{INK}" stroke-width="3"{J}/>')
    cloth = 'M110,46 L530,46 L530,196 L470,206 L420,186 Q370,206 320,228 Q270,206 220,186 L170,206 L110,196 Z'
    folds = ''.join(f'<path d="M{x},52 Q{x + 6},120 {x - 4},{176 + (x % 3) * 6}" stroke="#2a0402" stroke-width="2.4" fill="none" opacity=".5"/>' for x in (170, 250, 390, 470))
    nd, _ = centred('HONOR', 96, 166, 0.12, W)
    star = '0,-16 4.7,-6.5 15.2,-4.9 7.6,2.5 9.4,12.9 0,8 -9.4,12.9 -7.6,2.5 -15.2,-4.9 -4.7,-6.5'
    medal = (f'<path d="M308,222 L300,258 L320,250 L340,258 L332,222 Z" fill="#1a3a6a" stroke="{INK}" stroke-width="2.4"{J}/>'
             f'<circle cx="320" cy="272" r="22" fill="{gold}" stroke="{INK}" stroke-width="3"/><polygon points="{star}" transform="translate(320,273)" fill="#9a1a14" stroke="{INK}" stroke-width="1.6"/>')
    tass = ''.join(f'<path d="M{x},196 L{x},226" stroke="{gold}" stroke-width="3"/><circle cx="{x}" cy="230" r="4" fill="{gold}" stroke="{INK}" stroke-width="1.4"/>' for x in (110, 530))
    sub, sw = small(m, 'EARNED IN BATTLE', 15, 312, gold)
    body = (pole + f'<path d="{cloth}" fill="url(#{m.id("cl")})" stroke="{INK}" stroke-width="4"{J}/>{folds}<path d="M110,58 L530,58" stroke="{gold}" stroke-width="4"/>{tass}'
            + m.carve(nd, 8, gold) + medal + sub)
    return m.svg(body, 'Honor')

MARKS = {'raid_molten_core': magma, 'raid_onyxias_lair': veshmira, 'raid_tidecrown_citadel': tidecrown,
         'legend_lyveus': lyveus, 'legend_widya': widya, 'legend_bromli': bromli,
         'chapter_intro': prologue, 'chapter_ch1': ch1, 'chapter_ch2': ch2, 'chapter_ch3': ch3, 'chapter_ch4': ch4, 'chapter_ch5': ch5, 'chapter_ch6': ch6,
         'mode_trials': trials, 'mode_brawl': brawl, 'mode_honor': honor}

if __name__ == '__main__':
    only = [a for a in sys.argv[1:] if not a.startswith('--')]; marks = {}
    for k, f in MARKS.items():
        svg = f(); open(os.path.join(OUT, k + '.svg'), 'w').write(svg)
        flat = re.sub(r'<!--.*?-->', '', svg, flags=re.S); marks[k] = re.sub(r'>\s+<', '><', flat).strip()
    open(os.path.join(ROOT, 'src', 'art_marks.js'), 'w').write('// Generated by art/brand/marks.py; do not edit by hand.\n(function (root) { root.ART = root.ART || {}; root.ART.marks = '
        + json.dumps(marks) + '; })(typeof window !== \'undefined\' ? window : globalThis);\n')
    print(len(marks), 'marks,', sum(map(len, marks.values())) // 1024, 'KB')
    if '--sheet' in sys.argv:
        ks = only or list(MARKS); cols = 2 if only else 4; cw, chh = (640, 320) if only else (400, 200); rows = (len(ks) + cols - 1) // cols
        cells = ''.join(f'<image x="{i % cols * (cw + 12) + 6}" y="{i // cols * (chh + 12) + 6}" width="{cw}" height="{chh}" href="data:image/svg+xml;base64,'
                        + base64.b64encode(open(os.path.join(OUT, k + '.svg'), 'rb').read()).decode() + '"/>' for i, k in enumerate(ks))
        sp = os.path.join(H, '.sheet.svg')
        open(sp, 'w').write(f'<svg xmlns="http://www.w3.org/2000/svg" width="{cols * (cw + 12)}" height="{rows * (chh + 12)}"><rect width="100%" height="100%" fill="#0c0806"/>{cells}</svg>')
        subprocess.run(['rsvg-convert', '-o', os.path.join(H, 'marks_sheet.png'), sp], check=True); os.remove(sp)
        print('sheet', os.path.join(H, 'marks_sheet.png'))
